  assert.equal(await snapshot(),before,label+' Refresh must preserve complete project and history');
  const preview=page.locator('#asset-unused-preview');
  if(!await preview.isVisible())await page.locator('#asset-dependency-viewer details summary').first().click();
  const text=await preview.innerText();assert.match(text,/Read-only cleanup preview/);assert.match(text,/not deletion recommendations/);
