  for(const category of ['candidate','uncertain','known-reference','all']){await page.locator('#asset-unused-filter').selectOption(category);assert.equal(await snapshot(),before,label+' category filter must preserve full project/history');assert.equal(await page.locator('#asset-unused-status').innerText(),counts);}
  await preview.focus();await preview.press('PageDown');
  await page.locator('#asset-dependency-refresh').click();assert.equal(await preview.innerText(),text);assert.equal(await snapshot(),before,label+' navigation/repeated Refresh must be read-only');await preview.scrollIntoViewIfNeeded();
